<?php
 namespace QQWorld\Quote\Observer\Frontend\Quote\Address; class VatValidator { protected $customerAddress; protected $customerVat; public function __construct( \QQWorld\Customer\Helper\Address $customerAddress, \QQWorld\Customer\Model\Vat $customerVat ) { $this->customerVat = $customerVat; $this->customerAddress = $customerAddress; } public function validate(\QQWorld\Quote\Model\Quote\Address $quoteAddress, $store) { $customerCountryCode = $quoteAddress->getCountryId(); $customerVatNumber = $quoteAddress->getVatId(); $merchantCountryCode = $this->customerVat->getMerchantCountryCode(); $merchantVatNumber = $this->customerVat->getMerchantVatNumber(); $validationResult = null; if ($this->customerAddress->hasValidateOnEachTransaction( $store ) || $customerCountryCode != $quoteAddress->getValidatedCountryCode() || $customerVatNumber != $quoteAddress->getValidatedVatNumber() ) { $validationResult = $this->customerVat->checkVatNumber( $customerCountryCode, $customerVatNumber, $merchantVatNumber !== '' ? $merchantCountryCode : '', $merchantVatNumber ); $quoteAddress->setVatIsValid((int)$validationResult->getIsValid()); $quoteAddress->setVatRequestId($validationResult->getRequestIdentifier()); $quoteAddress->setVatRequestDate($validationResult->getRequestDate()); $quoteAddress->setVatRequestSuccess($validationResult->getRequestSuccess()); $quoteAddress->setValidatedVatNumber($customerVatNumber); $quoteAddress->setValidatedCountryCode($customerCountryCode); $quoteAddress->save(); } else { $validationResult = new \QQWorld\Framework\DataObject( [ 'is_valid' => (int)$quoteAddress->getVatIsValid(), 'request_identifier' => (string)$quoteAddress->getVatRequestId(), 'request_date' => (string)$quoteAddress->getVatRequestDate(), 'request_success' => (bool)$quoteAddress->getVatRequestSuccess(), ] ); } return $validationResult; } public function isEnabled(\QQWorld\Quote\Model\Quote\Address $quoteAddress, $store) { $configAddressType = $this->customerAddress->getTaxCalculationAddressType($store); $additionalBillingAddressCondition = $configAddressType == \QQWorld\Customer\Model\Address\AbstractAddress::TYPE_BILLING ? $configAddressType != $quoteAddress->getAddressType() : false; if (!$this->customerAddress->isVatValidationEnabled($store) || $additionalBillingAddressCondition) { return false; } return true; } } 